package com.ruoyi.medical.persistence;

import com.ruoyi.medical.contracts.WireValues;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

/** Exercises real transport routing/private staging bytes; writer is mocked, no S3 claim. */
class RuntimeObjectTransportTest {
 @TempDir Path directory;
 private RuntimeObjectLedger.Attempt attempt(boolean prior)throws Exception{
  String payload="{\"fixed\":true}";byte[] bytes=payload.getBytes(java.nio.charset.StandardCharsets.UTF_8);
  var write=new S3ObjectWriter.WriteIntent("00000000-0000-4000-8000-000000000001","runtime/00000000-0000-4000-8000-000000000003/00000000-0000-4000-8000-000000000005/00000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002",WireValues.sha256(bytes),Integer.toString(bytes.length),"application/json");
  var constructor=RuntimeObjectLedger.Intent.class.getDeclaredConstructors()[0];constructor.setAccessible(true);
  var intent=constructor.newInstance("key","00000000-0000-4000-8000-000000000002",RuntimeObjectLedger.Kind.REPLAY_MANIFEST,write,payload,"urn:medical:replay-manifest:1.0.0","a".repeat(64),"00000000-0000-4000-8000-000000000003","00000000-0000-4000-8000-000000000004","00000000-0000-4000-8000-000000000005");
  var attempt=RuntimeObjectLedger.Attempt.class.getDeclaredConstructors()[0];attempt.setAccessible(true);return (RuntimeObjectLedger.Attempt)attempt.newInstance(intent,prior);
 }
 private com.ruoyi.medical.contracts.InterfaceProtocol.ObjectRef reference(RuntimeObjectAttempt attempt){var i=attempt.writeIntent();return new com.ruoyi.medical.contracts.InterfaceProtocol.ObjectRef(i.objectKey(),"version-1",i.sha256(),i.sizeBytes(),i.mediaType());}
 private RuntimeObjectTransport transport(S3ObjectWriter writer)throws Exception{Files.setPosixFilePermissions(directory,PosixFilePermissions.fromString("rwx------"));return new RuntimeObjectTransport(()->writer,directory,1024);}
 @AfterEach void clear(){TransactionSynchronizationManager.setActualTransactionActive(false);}
 @Test void initialUsesExactPrivateBytesAndCleansTemporaryFile()throws Exception{
  var writer=mock(S3ObjectWriter.class);var attempted=attempt(false);var checks=new AtomicInteger();
  doAnswer(call->{Path file=call.getArgument(1);assertEquals(PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(file));assertArrayEquals(attempted.intent().bytes(),Files.readAllBytes(file));return reference(attempted);}).when(writer).writeVerified(any(),any(),any());
  transport(writer).transfer(attempted,()->checks.incrementAndGet());verify(writer).writeVerified(eq(attempted.intent().writeIntent()),any(),any());verify(writer,never()).recoverVerified(any(),any());assertTrue(checks.get()>=3);try(var files=Files.list(directory)){assertEquals(0,files.count());}verify(writer).close();
 }
 @Test void priorAttemptOnlyRecoversNeverWrites()throws Exception{var writer=mock(S3ObjectWriter.class);var attempted=attempt(true);when(writer.recoverVerified(any(),any())).thenReturn(reference(attempted));transport(writer).transfer(attempted,()->{});verify(writer).recoverVerified(eq(attempted.intent().writeIntent()),any());verify(writer,never()).writeVerified(any(),any(),any());}
 @Test void reusedInitialProofAfterUnknownSendCanOnlyRecover()throws Exception{var writer=mock(S3ObjectWriter.class);var attempted=attempt(false);var transport=transport(writer);when(writer.recoverVerified(any(),any())).thenReturn(reference(attempted));doThrow(new java.io.IOException("unknown send")).when(writer).writeVerified(any(),any(),any());assertThrows(java.io.IOException.class,()->transport.transfer(attempted,()->{}));transport.transfer(attempted,()->{});verify(writer,times(1)).writeVerified(any(),any(),any());verify(writer,times(1)).recoverVerified(eq(attempted.writeIntent()),any());}
 @Test void typedReadbackBindsActualPrivateAttemptAndCompleteVersion()throws Exception{var writer=mock(S3ObjectWriter.class);var attempted=attempt(true);var ref=reference(attempted);when(writer.recoverVerified(any(),any())).thenReturn(ref);var proof=transport(writer).transferVerified(attempted,()->{});assertSame(attempted,proof.originalAttempt());assertEquals(ref,proof.reference());assertEquals(ref.sha256(),proof.rawSha256());assertTrue(java.lang.reflect.Modifier.isPrivate(RuntimeObjectTransport.VerifiedTransfer.class.getDeclaredConstructors()[0].getModifiers()));}
 @Test void malformedSuccessfulReadbackCannotProduceTransferProof()throws Exception{var writer=mock(S3ObjectWriter.class);var attempted=attempt(true);var ref=reference(attempted);when(writer.recoverVerified(any(),any())).thenReturn(new com.ruoyi.medical.contracts.InterfaceProtocol.ObjectRef(ref.objectKey(),"version-2","f".repeat(64),ref.sizeBytes(),ref.mediaType()));assertThrows(TenantAccessException.class,()->transport(writer).transferVerified(attempted,()->{}));}
 @Test void currentRevocationBeforeTransferDoesNotOpenWriter()throws Exception{var writer=mock(S3ObjectWriter.class);assertThrows(TenantAccessException.class,()->transport(writer).transfer(attempt(false),()->{throw new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.ACCESS_DENIED);}));verifyNoInteractions(writer);}
 @Test void transactionIsNeverHeldAcrossObjectIo()throws Exception{var writer=mock(S3ObjectWriter.class);TransactionSynchronizationManager.setActualTransactionActive(true);assertThrows(TenantAccessException.class,()->transport(writer).transfer(attempt(false),()->{}));verifyNoInteractions(writer);}
 @Test void failedSendCleansPrivateBytesWithoutRetry()throws Exception{var writer=mock(S3ObjectWriter.class);doThrow(new java.io.IOException("unknown send")).when(writer).writeVerified(any(),any(),any());assertThrows(java.io.IOException.class,()->transport(writer).transfer(attempt(false),()->{}));verify(writer,never()).recoverVerified(any(),any());try(var files=Files.list(directory)){assertEquals(0,files.count());}verify(writer).close();}

 private void field(Object target,String name,Object value)throws Exception{var f=SourceUploadTransport.class.getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 private SourceUploadTransport deployed(TransferConcurrency concurrency,TransferConcurrency.Lease lease)throws Exception{
  var source=mock(SourceUploadTransport.class,CALLS_REAL_METHODS);field(source,"concurrency",concurrency);field(source,"limits",new TransferConcurrency.Limits("00000000-0000-4000-8000-000000000009",2,1,java.time.Duration.ofSeconds(5)));var policy=mock(SourceUploadTransportPolicy.class);when(policy.region()).thenReturn("test-region");when(policy.segmentBytes()).thenReturn(65536);field(source,"policy",policy);when(concurrency.acquire(anyString(),anyString(),any(),any())).thenReturn(lease);when(lease.guard(any())).thenCallRealMethod();return source;
 }
 @Test void deployedRouteUsesRealIdentityPermitAndReleasesOnUnknown()throws Exception{
  var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var original=attempt(false);Files.setPosixFilePermissions(directory,PosixFilePermissions.fromString("rwx------"));var transport=new RuntimeObjectTransport(source,directory,1024);
  try(var writers=mockConstruction(S3ObjectWriter.class,(writer,context)->{when(writer.writeVerified(any(),any(),any())).thenThrow(new java.io.IOException("unknown"));when(writer.recoverVerified(any(),any())).thenReturn(reference(original));})){
   assertThrows(java.io.IOException.class,()->transport.transferVerified(original,()->{}));transport.transferVerified(original,()->{});assertEquals(2,writers.constructed().size());verify(writers.constructed().get(0)).writeVerified(any(),any(),any());verify(writers.constructed().get(1)).recoverVerified(any(),any());for(var writer:writers.constructed())verify(writer).close();
  }verify(c,times(2)).acquire(eq(original.tenantId()),eq(original.actorId()),any(),any());verify(lease,times(2)).close();
 }
 @Test void sourceRouteStillRejectsRuntimeKeyBeforePermit()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var a=attempt(false);assertThrows(TenantAccessException.class,()->source.writeSourceJob(a.tenantId(),a.actorId(),a.writeIntent(),directory.resolve("unused"),directory,false,1024,()->{}));verifyNoInteractions(c,lease);}
 @Test void fixedKeyTamperCannotReachPermit()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var a=attempt(false);var f=RuntimeObjectLedger.Intent.class.getDeclaredField("intent");f.setAccessible(true);var i=a.writeIntent();f.set(a.intent(),new S3ObjectWriter.WriteIntent(i.writeId(),"arbitrary/other-tenant",i.sha256(),i.sizeBytes(),i.mediaType()));assertThrows(TenantAccessException.class,()->source.writeRuntimeObject(a,directory,1024,()->{}));verifyNoInteractions(c,lease);}
 @Test void hashTamperCannotReachPermit()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var a=attempt(false);var f=RuntimeObjectLedger.Intent.class.getDeclaredField("intent");f.setAccessible(true);var i=a.writeIntent();f.set(a.intent(),new S3ObjectWriter.WriteIntent(i.writeId(),i.objectKey(),"b".repeat(64),i.sizeBytes(),i.mediaType()));assertThrows(TenantAccessException.class,()->source.writeRuntimeObject(a,directory,1024,()->{}));verifyNoInteractions(c,lease);}
 @Test void deployedRevocationBeforePermitDoesNotSend()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);assertThrows(TenantAccessException.class,()->source.writeRuntimeObject(attempt(false),directory,1024,()->{throw new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.ACCESS_DENIED);}));verifyNoInteractions(c,lease);}

 @Test void revokedAfterReadbackClosesPermitWithoutTransferProof()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var a=attempt(false);Files.setPosixFilePermissions(directory,PosixFilePermissions.fromString("rwx------"));var revoked=new java.util.concurrent.atomic.AtomicBoolean();try(var writers=mockConstruction(S3ObjectWriter.class,(writer,context)->when(writer.writeVerified(any(),any(),any())).thenAnswer(call->{revoked.set(true);return reference(a);}))) {assertThrows(TenantAccessException.class,()->source.writeRuntimeObject(a,directory,1024,()->{if(revoked.get())throw new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.ACCESS_DENIED);}));verify(writers.constructed().get(0)).close();}verify(lease).close();}

 @Test void originalSourcePrefixStillUsesItsOwnWriterAndPermit()throws Exception{var c=mock(TransferConcurrency.class);var lease=mock(TransferConcurrency.Lease.class);var source=deployed(c,lease);var a=attempt(false);var i=a.writeIntent();var original=new S3ObjectWriter.WriteIntent(i.writeId(),"tenants/"+a.tenantId()+"/source-parsed/fixed",i.sha256(),i.sizeBytes(),i.mediaType());var reference=new com.ruoyi.medical.contracts.InterfaceProtocol.ObjectRef(original.objectKey(),"source-version",i.sha256(),i.sizeBytes(),i.mediaType());try(var writers=mockConstruction(S3ObjectWriter.class,(writer,context)->when(writer.recoverVerified(eq(original),any())).thenReturn(reference))){assertEquals(reference,source.writeSourceJob(a.tenantId(),a.actorId(),original,directory.resolve("unused"),directory,true,1024,()->{}));verify(writers.constructed().get(0),never()).writeVerified(any(),any(),any());verify(writers.constructed().get(0)).close();}verify(lease).close();}
}
